fn print_error(msg: &str) {
    eprintln!("\x1b[31m[ERROR]\x1b[0m {}", msg);
}
fn print_warn(msg: &str) {
    eprintln!("\x1b[33m[WARN]\x1b[0m {}", msg);
}
fn print_info(msg: &str) {
    eprintln!("\x1b[34m[INFO]\x1b[0m {}", msg);
}
fn print_success(path: &str) {
    eprintln!("\x1b[32m[SUCCESS]\x1b[0m Snapshot saved to {} successful!", path);
}

fn default_config_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string());
    PathBuf::from(home).join(".config").join("codesnap").join("config.json")
}
fn remote_themes_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string());
    PathBuf::from(home).join(".config").join("codesnap").join("remote_themes")
}

fn ensure_default_config(silent: bool) -> Result<bool, ()> {
    // Returns true if created
    let cfg_path = default_config_path();
    if cfg_path.exists() {
        return Ok(false);
    }
    // Ensure parent dir exists
    if let Some(parent) = cfg_path.parent() {
        if let Err(_) = fs::create_dir_all(parent) {
            // If fails, ignore? Original creates dir and succeeds?
        }
    }
    // Write default config
    if fs::write(&cfg_path, DEFAULT_CONFIG_JSON).is_err() {
        // If fails, we still try?
        return Ok(false);
    }
    if !silent {
        // Actually original prints INFO even with silent? Wait earlier we saw INFO printed even with silent for default creation.
        // Let's check: earlier we tested silent with no code and INFO was printed. So INFO is printed regardless of silent?
        // Actually we observed INFO printed even with silent for default creation. So always print INFO when created unless custom config?
        // For custom config valid, default config should NOT be created, but remote dir created.
        // So for default case, print INFO always, even if silent? Let's see earlier: 
        // rm -rf config, then --silent success: we saw INFO printed even with silent.
        // So INFO is not suppressed by silent.
        // Wait earlier we had: rm -rf, then --silent success: output showed INFO printed. Yes.
        // So INFO is always printed when auto created, regardless of silent.
        // But SUCCESS is suppressed by silent.
        // We'll print INFO regardless of silent flag for default creation.
        print_info(&format!("Automated created config file at \"{}\"", cfg_path.display()));
    } else {
        // Even with silent, original still prints INFO? Let's check again: we saw silent success still printed INFO.
        print_info(&format!("Automated created config file at \"{}\"", cfg_path.display()));
    }
    Ok(true)
}

fn ensure_remote_themes_dir() {
    let p = remote_themes_path();
    let _ = fs::create_dir_all(p);
}

fn parse_range(s: &str) -> Result<(Option<u64>, Option<u64>), String> {
    // Returns error string to be printed
    // Logic:
    // - If contains more than one colon, Invalid range format
    // - If exactly one colon, split into left and right
    //   - left empty => None, right empty => None, but both empty => cannot parse integer from empty string
    //   - each non-empty must parse to u64, else invalid digit found in string
    // - If no colon, single number, parse u64, else invalid digit
    let colon_count = s.matches(':').count();
    if colon_count > 1 {
        return Err("Invalid range format".to_string());
    }
    if colon_count == 1 {
        let parts: Vec<&str> = s.split(':').collect();
        let left = parts[0];
        let right = parts[1];
        if left.is_empty() && right.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        let l_opt = if left.is_empty() {
            None
        } else {
            match left.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        let r_opt = if right.is_empty() {
            None
        } else {
            match right.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        Ok((l_opt, r_opt))
    } else {
        // no colon
        if s.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        match s.parse::<u64>() {
            Ok(v) => Ok((Some(v), Some(v))),
            Err(_) => Err("invalid digit found in string".to_string()),
        }
    }
}

