fn parse_range(s: &str) -> Result<(Option<u64>, Option<u64>), String> {
    // Returns error string to be printed
    // Logic:
    // - If contains more than one colon, Invalid range format
    // - If exactly one colon, split into left and right
    //   - left empty => None, right empty => None, but both empty => cannot parse integer from empty string
    //   - each non-empty must parse to u64, else invalid digit found in string
    // - If no colon, single number, parse u64, else invalid digit
    let colon_count = s.matches(':').count();
    if colon_count > 1 {
        return Err("Invalid range format".to_string());
    }
    if colon_count == 1 {
        let parts: Vec<&str> = s.split(':').collect();
        let left = parts[0];
        let right = parts[1];
        if left.is_empty() && right.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        let l_opt = if left.is_empty() {
            None
        } else {
            match left.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        let r_opt = if right.is_empty() {
            None
        } else {
            match right.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        Ok((l_opt, r_opt))
    } else {
        // no colon
        if s.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        match s.parse::<u64>() {
            Ok(v) => Ok((Some(v), Some(v))),
            Err(_) => Err("invalid digit found in string".to_string()),
        }
    }
}

