fn ensure_default_config() -> Result<bool, ()> {
    let cfg_path = default_config_path();
    if cfg_path.exists() {
        return Ok(false);
    }
    if let Some(parent) = cfg_path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    if fs::write(&cfg_path, DEFAULT_CONFIG_JSON).is_err() {
        return Ok(false);
    }
    print_info(&format!("Automated created config file at \"{}\"", cfg_path.display()));
    Ok(true)
}

