        }
    }
    if let Some(raw) = &cli.raw_highlight_lines {
        match serde_json::from_str::<serde_json::Value>(raw) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    }

    // Manual clap-like checks for fields that should be clap errors (exit 2, no config)
    if cli.scale_factor.parse::<u64>().is_err() {
        if !has_custom_config {
            let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
        }
        eprintln!("error: invalid value '{}' for '--scale-factor <SCALE_FACTOR>': invalid digit found in string", cli.scale_factor);
