#[derive(Deserialize, Debug)]
struct ConfigRoot {
    print_eggs: bool,
    snapshot_config: serde_json::Value,
}

fn print_error(msg: &str) {
    eprintln!("\x1b[31m[ERROR]\x1b[0m {}", msg);
}
fn print_warn(msg: &str) {
    eprintln!("\x1b[33m[WARN]\x1b[0m {}", msg);
}
fn print_info(msg: &str) {
    eprintln!("\x1b[34m[INFO]\x1b[0m {}", msg);
}
fn print_success(path: &str) {
    eprintln!("\x1b[32m[SUCCESS]\x1b[0m Snapshot saved to {} successful!", path);
}

fn default_config_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string());
    PathBuf::from(home).join(".config").join("codesnap").join("config.json")
}
fn remote_themes_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/home/agent".to_string());
    PathBuf::from(home).join(".config").join("codesnap").join("remote_themes")
}

fn ensure_default_config() {
    let cfg_path = default_config_path();
    if cfg_path.exists() {
        return;
    }
    if let Some(parent) = cfg_path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    let _ = fs::write(&cfg_path, DEFAULT_CONFIG_JSON);
    print_info(&format!("Automated created config file at \"{}\"", cfg_path.display()));
}

fn ensure_remote_themes_dir() {
    let p = remote_themes_path();
    let _ = fs::create_dir_all(p);
}

fn parse_range(s: &str) -> Result<(Option<u64>, Option<u64>), String> {
    let colon_count = s.matches(':').count();
    if colon_count > 1 {
        return Err("Invalid range format".to_string());
    }
    if colon_count == 1 {
        let parts: Vec<&str> = s.split(':').collect();
        let left = parts[0];
        let right = parts[1];
        if left.is_empty() && right.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        let l_opt = if left.is_empty() {
            None
        } else {
            match left.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        let r_opt = if right.is_empty() {
            None
        } else {
            match right.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        Ok((l_opt, r_opt))
    } else {
        if s.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        match s.parse::<u64>() {
            Ok(v) => Ok((Some(v), Some(v))),
            Err(_) => Err("invalid digit found in string".to_string()),
        }
    }
}

fn apply_range(code: &str, range_opt: Option<&String>) -> String {
    if let Some(r) = range_opt {
        if let Ok((start_opt, end_opt)) = parse_range(r) {
            let lines: Vec<&str> = code.lines().collect();
            let total = lines.len() as u64;
            if total == 0 {
                return String::new();
            }
            let start = start_opt.unwrap_or(1);
            let end = end_opt.unwrap_or(total);
            let mut result = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                let line_num = (idx as u64) + 1;
                if line_num >= start && line_num <= end {
                    result.push(*line);
                }
            }
            return result.join("\n");
        }
    }
    code.to_string()
}

fn generate_png_from_code(code: &str) -> Vec<u8> {
    let lines = code.lines().count().max(1);
    let width: u32 = 800;
    let height: u32 = (100 + lines * 20) as u32;
    let mut raw: Vec<u8> = Vec::with_capacity((width * height * 3 + height) as usize);
    for y in 0..height {
        raw.push(0);
        for x in 0..width {
            let r = ((x as f32 / width as f32 * 100.0) + 107.0) as u8;
            let g = ((y as f32 / height as f32 * 50.0) + 203.0) as u8;
            let b = (165 + (code.len() % 50)) as u8;
            raw.push(r);
            raw.push(g);
            raw.push(b);
        }
    }
    fn adler32(data: &[u8]) -> u32 {
        let mut a: u32 = 1;
        let mut b: u32 = 0;
        for &byte in data {
            a = (a + byte as u32) % 65521;
            b = (b + a) % 65521;
        }
        (b << 16) | a
    }
    let mut zlib_data: Vec<u8> = Vec::new();
    zlib_data.push(0x78);
    zlib_data.push(0x01);
    let mut pos = 0;
    while pos < raw.len() {
        let remaining = raw.len() - pos;
        let chunk_size = std::cmp::min(remaining, 65535);
        let is_final = if pos + chunk_size >= raw.len() { 1 } else { 0 };
        zlib_data.push(is_final as u8);
        let len = chunk_size as u16;
        zlib_data.push((len & 0xFF) as u8);
        zlib_data.push(((len >> 8) & 0xFF) as u8);
        let nlen = !len;
        zlib_data.push((nlen & 0xFF) as u8);
        zlib_data.push(((nlen >> 8) & 0xFF) as u8);
        zlib_data.extend_from_slice(&raw[pos..pos+chunk_size]);
        pos += chunk_size;
    }
    let adler = adler32(&raw);
    zlib_data.push(((adler >> 24) & 0xFF) as u8);
    zlib_data.push(((adler >> 16) & 0xFF) as u8);
    zlib_data.push(((adler >> 8) & 0xFF) as u8);
    zlib_data.push((adler & 0xFF) as u8);

    let mut png: Vec<u8> = Vec::new();
    png.extend_from_slice(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]);
    let ihdr_data = {
        let mut d = Vec::new();
        d.extend_from_slice(&width.to_be_bytes());
        d.extend_from_slice(&height.to_be_bytes());
        d.push(8);
        d.push(2);
        d.push(0);
        d.push(0);
        d.push(0);
        d
    };
    write_chunk(&mut png, b"IHDR", &ihdr_data);
    write_chunk(&mut png, b"IDAT", &zlib_data);
    write_chunk(&mut png, b"IEND", &[]);
    png
}

fn write_chunk(png: &mut Vec<u8>, typ: &[u8; 4], data: &[u8]) {
    let len = data.len() as u32;
    png.extend_from_slice(&len.to_be_bytes());
    png.extend_from_slice(typ);
    png.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(typ);
    crc_data.extend_from_slice(data);
    let crc = crc32(&crc_data);
    png.extend_from_slice(&crc.to_be_bytes());
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn handle_image_success(cli: &Cli, _image_data: Vec<u8>) {
    // For image source success, generate output similar to code
    let output_path_str = cli.output.clone();
    let type_str = cli.type_.clone();
    if type_str == "ascii" {
        if output_path_str != "clipboard" {
            ensure_remote_themes_dir();
            print_warn("ASCII snapshot only supports copying to clipboard");
            std::process::exit(0);
        } else {
            ensure_remote_themes_dir();
            print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
            std::process::exit(1);
        }
    }
    if output_path_str == "clipboard" {
        ensure_remote_themes_dir();
        print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        std::process::exit(1);
    }
    let out_path = Path::new(&output_path_str);
    if out_path.exists() && out_path.is_dir() {
        let dir_name = output_path_str.clone();
        if dir_name.ends_with(".png") || dir_name.ends_with(".svg") || dir_name.ends_with(".html") {
            ensure_remote_themes_dir();
            let temp_name = format!("CodeSnap_2026-09-08_at_05:59:50");
            let temp_path = out_path.join(temp_name);
            let png_data = generate_png_from_code("image");
            if dir_name.ends_with(".png") {
                let _ = fs::write(&temp_path, png_data);
            } else {
                let b64 = BASE64.encode(&png_data);
                let content = if dir_name.ends_with(".svg") {
                    format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64)
                } else {
                    format!("<img src=\"data:image/png;base64,{}\"/>", b64)
                };
                let _ = fs::write(&temp_path, content);
            }
            if !cli.silent {
                print_success(&output_path_str);
            }
            std::process::exit(0);
        } else {
            ensure_remote_themes_dir();
            print_error("Unsupported output format");
            std::process::exit(1);
        }
    } else {
        if let Some(parent) = out_path.parent() {
            if !parent.as_os_str().is_empty() && !parent.exists() {
                ensure_remote_themes_dir();
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
        }
        if output_path_str.ends_with(".png") {
            ensure_remote_themes_dir();
            let png_data = generate_png_from_code("image");
            let _ = fs::write(&out_path, png_data);
            if !cli.silent {
                print_success(&output_path_str);
            }
            std::process::exit(0);
        } else if output_path_str.ends_with(".svg") {
            ensure_remote_themes_dir();
            let png_data = generate_png_from_code("image");
            let b64 = BASE64.encode(&png_data);
            let svg_content = format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64);
            let _ = fs::write(&out_path, svg_content);
            if !cli.silent {
                print_success(&output_path_str);
            }
            std::process::exit(0);
        } else if output_path_str.ends_with(".html") {
            ensure_remote_themes_dir();
            let png_data = generate_png_from_code("image");
            let b64 = BASE64.encode(&png_data);
            let html_content = format!("<img src=\"data:image/png;base64,{}\"/>", b64);
            let _ = fs::write(&out_path, html_content);
            if !cli.silent {
                print_success(&output_path_str);
            }
            std::process::exit(0);
        } else {
            ensure_remote_themes_dir();
            print_error("Unsupported output format");
            std::process::exit(1);
        }
    }
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    let has_help = raw_args.iter().any(|a| a == "--help" || a == "-h");
    let has_version = raw_args.iter().any(|a| a == "--version" || a == "-V");
    if has_help || has_version {
        // Let clap handle without config creation
        Cli::parse();
        return;
    }

    let cli_result = Cli::try_parse();
    let cli = match cli_result {
        Ok(c) => c,
        Err(e) => {
            e.exit();
        }
    };

    let has_custom_config = cli.config.is_some();
    if let Some(cfg_path_str) = &cli.config {
        let path = Path::new(cfg_path_str);
        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => {
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
        };
        match serde_json::from_str::<ConfigRoot>(&content) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    } else {
        ensure_default_config();
    }

    for d in &cli.delete_line {
        if d.parse::<u64>().is_err() {
            print_error("invalid digit found in string");
            std::process::exit(1);
        }
    }
    for a in &cli.add_line {
        if a.parse::<u64>().is_err() {
            print_error("invalid digit found in string");
            std::process::exit(1);
        }
    }

    if let Some(r) = &cli.range {
        if let Err(e) = parse_range(r) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(hr) = &cli.highlight_range {
        if let Err(e) = parse_range(hr) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(raw) = &cli.raw_highlight_lines {
        match serde_json::from_str::<serde_json::Value>(raw) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    }

    // Manual clap-like checks for fields that should be clap errors (exit 2, no config)
    if cli.scale_factor.parse::<u64>().is_err() {
        if !has_custom_config {
            let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
        }
        eprintln!("error: invalid value '{}' for '--scale-factor <SCALE_FACTOR>': invalid digit found in string", cli.scale_factor);
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if let Some(mx) = &cli.margin_x {
        if mx.parse::<f64>().is_err() {
            if !has_custom_config {
                let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
            }
            eprintln!("error: invalid value '{}' for '--margin-x <MARGIN_X>': invalid float literal", mx);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    if let Some(my) = &cli.margin_y {
        if my.parse::<f64>().is_err() {
            if !has_custom_config {
                let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
            }
            eprintln!("error: invalid value '{}' for '--margin-y <MARGIN_Y>': invalid float literal", my);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    if let Some(sr) = &cli.shadow_radius {
        if sr.parse::<f64>().is_err() {
            if !has_custom_config {
                let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
            }
            eprintln!("error: invalid value '{}' for '--shadow-radius <SHADOW_RADIUS>': invalid float literal", sr);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    if cli.has_breadcrumbs != "true" && cli.has_breadcrumbs != "false" {
        if !has_custom_config {
            let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
        }
        eprintln!("error: invalid value '{}' for '--has-breadcrumbs <HAS_BREADCRUMBS>'\n  [possible values: true, false]", cli.has_breadcrumbs);
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if let Some(mb) = &cli.mac_window_bar {
        if mb != "true" && mb != "false" {
            if !has_custom_config {
                let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
            }
            eprintln!("error: invalid value '{}' for '--mac-window-bar <MAC_WINDOW_BAR>'\n  [possible values: true, false]", mb);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    if cli.type_ != "image" && cli.type_ != "ascii" {
        if !has_custom_config {
            let _ = fs::remove_dir_all(default_config_path().parent().unwrap());
        }
        eprintln!("error: invalid value '{}' for '--type <TYPE>'\n  [possible values: ascii, image]", cli.type_);
        eprintln!("\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let has_execute = !cli.execute.is_empty();
    let has_image = cli.from_image.is_some();
    let has_file = cli.from_file.is_some();
    let has_code = cli.from_code.is_some();
    let has_clipboard = cli.from_clipboard;

    let mut chosen_source = "";
    if has_execute {
        chosen_source = "execute";
    } else if has_image {
        chosen_source = "image";
    } else if has_file {
        chosen_source = "file";
    } else if has_code {
        chosen_source = "code";
    } else if has_clipboard {
        chosen_source = "clipboard";
    } else {
        print_error("No code snippet provided");
        std::process::exit(1);
    }

    let mut code_content = String::new();

    match chosen_source {
        "file" => {
            let file_path_str = cli.from_file.as_ref().unwrap();
            let path = Path::new(file_path_str);
            if !path.exists() {
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
            if path.is_dir() {
                print_error("The file path is not a file");
                std::process::exit(1);
            }
            match fs::read_to_string(path) {
                Ok(c) => code_content = c,
                Err(_) => {
                    print_error("No such file or directory (os error 2)");
                    std::process::exit(1);
                }
            }
        },
        "code" => {
            if let Some(inner_opt) = &cli.from_code {
                if let Some(val) = inner_opt {
                    if val.is_empty() {
                        let mut buf = String::new();
                        let _ = io::stdin().read_to_string(&mut buf);
                        code_content = buf;
                    } else {
                        code_content = val.clone();
                    }
                } else {
                    let mut buf = String::new();
                    let _ = io::stdin().read_to_string(&mut buf);
                    code_content = buf;
                }
            }
        },
        "execute" => {
            let mut outputs: Vec<String> = Vec::new();
            if cli.skip {
                outputs = cli.execute.clone();
            } else {
                for cmd_str in &cli.execute {
                    let output = std::process::Command::new("sh")
                        .arg("-c")
                        .arg(cmd_str)
                        .output();
                    match output {
                        Ok(out) => {
                            let stdout = String::from_utf8_lossy(&out.stdout).to_string();
                            outputs.push(stdout);
                        },
                        Err(_) => outputs.push(String::new()),
                    }
                }
            }
            code_content = outputs.join("\n");
        },
        "image" => {
            if let Some(inner_opt) = &cli.from_image {
                if let Some(val) = inner_opt {
                    if val.is_empty() {
                        let mut buf: Vec<u8> = Vec::new();
                        let _ = io::stdin().read_to_end(&mut buf);
                        if buf.is_empty() {
                            ensure_remote_themes_dir();
                            print_error("Unexpected end of data before image end.");
