        .arg(Arg::new("scale-factor").long("scale-factor").value_name("SCALE_FACTOR").default_value("3").value_parser(clap::value_parser!(u64)).help("CodeSnap supports scaling the snapshot, the default scale factor is 3 for better quality\n\n[default: 3]"))
        .arg(Arg::new("title-font-family").long("title-font-family").value_name("TITLE_FONT_FAMILY").help("Title font family"))
        .arg(Arg::new("title-color").long("title-color").value_name("TITLE_COLOR").help("Title font color"))
        .arg(Arg::new("background").long("background").value_name("BACKGROUND").help("Set background color of the snapshot"))
        .arg(Arg::new("type").long("type").value_name("TYPE").default_value("image").value_parser(["ascii","image"]).help("[default: image]\n[possible values: ascii, image]"))
        .arg(Arg::new("config").long("config").value_name("CONFIG").help(""));

    let matches = cmd.get_matches();

    let silent = matches.get_flag("silent");

    // Check custom config
    let has_custom_config = matches.contains_id("config") && matches.get_one::<String>("config").is_some();
    if let Some(cfg_path_str) = matches.get_one::<String>("config") {
        let path = Path::new(cfg_path_str);
        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => {
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
        };
        match serde_json::from_str::<ConfigRoot>(&content) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    } else {
        ensure_default_config();
    }

    // Validate delete-line and add-line
    if let Some(vals) = matches.get_many::<String>("delete-line") {
        for v in vals {
            if v.parse::<u64>().is_err() {
                print_error("invalid digit found in string");
                std::process::exit(1);
            }
        }
    }
    if let Some(vals) = matches.get_many::<String>("add-line") {
        for v in vals {
            if v.parse::<u64>().is_err() {
                print_error("invalid digit found in string");
                std::process::exit(1);
            }
        }
    }

    if let Some(r) = matches.get_one::<String>("range") {
        if let Err(e) = parse_range(r) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(hr) = matches.get_one::<String>("highlight-range") {
        if let Err(e) = parse_range(hr) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(raw) = matches.get_one::<String>("raw-highlight-lines") {
        match serde_json::from_str::<serde_json::Value>(raw) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    }

    let has_execute = matches.contains_id("execute");
    let has_image = matches.contains_id("from-image");
    let has_file = matches.contains_id("from-file");
    let has_code = matches.contains_id("from-code");
    let has_clipboard = matches.get_flag("from-clipboard");

    let mut chosen_source = "";
    if has_execute {
        chosen_source = "execute";
    } else if has_image {
        chosen_source = "image";
    } else if has_file {
        chosen_source = "file";
    } else if has_code {
