cat > src/main.rs <<'RS'
use clap::{Arg, ArgAction, Command};
use serde::Deserialize;
use std::path::{Path, PathBuf};
use std::fs;
use std::io::{self, Read};
use base64::{Engine as _, engine::general_purpose::STANDARD as BASE64};

const DEFAULT_CONFIG_JSON: &str = r##"{
  "print_eggs": false,
  "snapshot_config": {
    "theme": "candy",
    "window": {
      "mac_window_bar": true,
