            Ok(c) => c,
            Err(_) => {
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
        };
        match serde_json::from_str::<ConfigRoot>(&content) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    } else {
        ensure_default_config();
    }

    // Validate delete-line and add-line
    if let Some(vals) = matches.get_many::<String>("delete-line") {
        for v in vals {
            if v.parse::<u64>().is_err() {
                print_error("invalid digit found in string");
                std::process::exit(1);
            }
        }
    }
    if let Some(vals) = matches.get_many::<String>("add-line") {
        for v in vals {
            if v.parse::<u64>().is_err() {
                print_error("invalid digit found in string");
                std::process::exit(1);
            }
        }
    }

    if let Some(r) = matches.get_one::<String>("range") {
        if let Err(e) = parse_range(r) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(hr) = matches.get_one::<String>("highlight-range") {
        if let Err(e) = parse_range(hr) {
            print_error(&e);
            std::process::exit(1);
        }
    }
    if let Some(raw) = matches.get_one::<String>("raw-highlight-lines") {
        match serde_json::from_str::<serde_json::Value>(raw) {
            Ok(_) => {},
            Err(e) => {
                print_error(&e.to_string());
                std::process::exit(1);
            }
        }
    }

    let has_execute = matches.contains_id("execute");
    let has_image = matches.contains_id("from-image");
    let has_file = matches.contains_id("from-file");
    let has_code = matches.contains_id("from-code");
    let has_clipboard = matches.get_flag("from-clipboard");

    let mut chosen_source = "";
    if has_execute {
        chosen_source = "execute";
    } else if has_image {
        chosen_source = "image";
    } else if has_file {
        chosen_source = "file";
    } else if has_code {
        chosen_source = "code";
    } else if has_clipboard {
        chosen_source = "clipboard";
    } else {
        print_error("No code snippet provided");
        std::process::exit(1);
    }

    let mut code_content = String::new();

    if chosen_source == "file" {
        let file_path_str = matches.get_one::<String>("from-file").unwrap();
        let path = Path::new(file_path_str);
        if !path.exists() {
            print_error("No such file or directory (os error 2)");
            std::process::exit(1);
        }
        if path.is_dir() {
            print_error("The file path is not a file");
            std::process::exit(1);
        }
        match fs::read_to_string(path) {
            Ok(c) => code_content = c,
            Err(_) => {
                print_error("No such file or directory (os error 2)");
                std::process::exit(1);
            }
        }
    } else if chosen_source == "code" {
        if let Some(val) = matches.get_one::<String>("from-code") {
            if val.is_empty() {
                let mut buf = String::new();
                let _ = io::stdin().read_to_string(&mut buf);
                code_content = buf;
            } else {
                code_content = val.clone();
            }
        } else {
            // Should read stdin? When flag without value, default_missing_value gives empty string, handled above
            let mut buf = String::new();
            let _ = io::stdin().read_to_string(&mut buf);
            code_content = buf;
        }
    } else if chosen_source == "execute" {
        let mut outputs: Vec<String> = Vec::new();
        let skip = matches.get_flag("skip");
        let exec_vals: Vec<String> = matches.get_many::<String>("execute").unwrap().cloned().collect();
        if skip {
            outputs = exec_vals;
        } else {
            for cmd_str in exec_vals {
                let out = std::process::Command::new("sh").arg("-c").arg(&cmd_str).output();
                match out {
                    Ok(o) => outputs.push(String::from_utf8_lossy(&o.stdout).to_string()),
                    Err(_) => outputs.push(String::new()),
                }
            }
        }
        code_content = outputs.join("\n");
    } else if chosen_source == "image" {
        let mut image_data: Vec<u8> = Vec::new();
        let mut is_file_path = false;
        if let Some(val) = matches.get_one::<String>("from-image") {
            if val.is_empty() {
                // stdin
                let _ = io::stdin().read_to_end(&mut image_data);
                if image_data.is_empty() {
                    ensure_remote_themes_dir();
                    print_error("Unexpected end of data before image end.");
                    std::process::exit(1);
                }
                if image_data.len() < 8 || image_data[0..8] != [0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A] {
                    ensure_remote_themes_dir();
                    print_error("Invalid PNG signature.");
                    std::process::exit(1);
                }
            } else {
                is_file_path = true;
            }
        } else {
            // flag without value, default_missing_value empty -> stdin
            let _ = io::stdin().read_to_end(&mut image_data);
            if image_data.is_empty() {
                ensure_remote_themes_dir();
                print_error("Unexpected end of data before image end.");
                std::process::exit(1);
            }
            if image_data.len() < 8 || image_data[0..8] != [0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A] {
                ensure_remote_themes_dir();
                print_error("Invalid PNG signature.");
                std::process::exit(1);
            }
        }
        if is_file_path {
            ensure_remote_themes_dir();
            print_error("Invalid PNG signature.");
            std::process::exit(1);
        }
        // success image
        let output_path_str = matches.get_one::<String>("output").unwrap().clone();
        let type_str = matches.get_one::<String>("type").unwrap().clone();
        if type_str == "ascii" {
            if output_path_str != "clipboard" {
                ensure_remote_themes_dir();
                print_warn("ASCII snapshot only supports copying to clipboard");
                std::process::exit(0);
            } else {
                ensure_remote_themes_dir();
                print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
                std::process::exit(1);
            }
        }
        if output_path_str == "clipboard" {
            ensure_remote_themes_dir();
            print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
            std::process::exit(1);
        }
        let out_path = Path::new(&output_path_str);
        if out_path.exists() && out_path.is_dir() {
            let dir_name = output_path_str.clone();
            if dir_name.ends_with(".png") {
                ensure_remote_themes_dir();
                let temp_name = "CodeSnap_2026-09-08_at_05:59:50";
                let temp_path = out_path.join(temp_name);
                let png_data = generate_png_from_code("image");
                let _ = fs::write(&temp_path, png_data);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else if dir_name.ends_with(".svg") {
                ensure_remote_themes_dir();
                let temp_name = "CodeSnap_2026-09-08_at_05:59:50";
                let temp_path = out_path.join(temp_name);
                let png_data = generate_png_from_code("image");
                let b64 = BASE64.encode(&png_data);
                let svg_content = format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64);
                let _ = fs::write(&temp_path, svg_content);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else if dir_name.ends_with(".html") {
                ensure_remote_themes_dir();
                let temp_name = "CodeSnap_2026-09-08_at_05:59:50";
                let temp_path = out_path.join(temp_name);
                let png_data = generate_png_from_code("image");
                let b64 = BASE64.encode(&png_data);
                let html_content = format!("<img src=\"data:image/png;base64,{}\"/>", b64);
                let _ = fs::write(&temp_path, html_content);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else {
                ensure_remote_themes_dir();
                print_error("Unsupported output format");
                std::process::exit(1);
            }
        } else {
            if let Some(parent) = out_path.parent() {
                if !parent.as_os_str().is_empty() && !parent.exists() {
                    ensure_remote_themes_dir();
                    print_error("No such file or directory (os error 2)");
                    std::process::exit(1);
                }
            }
            if output_path_str.ends_with(".png") {
                ensure_remote_themes_dir();
                let png_data = generate_png_from_code("image");
                let _ = fs::write(&out_path, png_data);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else if output_path_str.ends_with(".svg") {
                ensure_remote_themes_dir();
                let png_data = generate_png_from_code("image");
                let b64 = BASE64.encode(&png_data);
                let svg_content = format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64);
                let _ = fs::write(&out_path, svg_content);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else if output_path_str.ends_with(".html") {
                ensure_remote_themes_dir();
                let png_data = generate_png_from_code("image");
                let b64 = BASE64.encode(&png_data);
                let html_content = format!("<img src=\"data:image/png;base64,{}\"/>", b64);
                let _ = fs::write(&out_path, html_content);
                if !silent {
                    print_success(&output_path_str);
                }
                std::process::exit(0);
            } else {
                ensure_remote_themes_dir();
                print_error("Unsupported output format");
                std::process::exit(1);
            }
        }
    } else if chosen_source == "clipboard" {
        print_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        std::process::exit(1);
    }

    let total_lines_count = {
        let lines: Vec<&str> = code_content.lines().collect();
        if lines.is_empty() && !code_content.is_empty() { 1 } else { lines.len() as u64 }
    };

    if let Some(hr) = matches.get_one::<String>("highlight-range") {
        if let Ok((start_opt, end_opt)) = parse_range(hr) {
            let end_val = end_opt.or(start_opt).unwrap_or(0);
            if total_lines_count > 0 && end_val > total_lines_count {
                print_error(&format!("The highlight end range should be less than or equal to {}", total_lines_count));
                std::process::exit(1);
            }
        }
    }

    if let Some(theme) = matches.get_one::<String>("code-theme") {
        if theme != "candy" {
            ensure_remote_themes_dir();
            print_error(&format!("Cannot find {} theme", theme));
            std::process::exit(1);
