}

fn parse_range(s: &str) -> Result<(Option<u64>, Option<u64>), String> {
    let colon_count = s.matches(':').count();
    if colon_count > 1 {
        return Err("Invalid range format".to_string());
    }
    if colon_count == 1 {
        let parts: Vec<&str> = s.split(':').collect();
        let left = parts[0];
        let right = parts[1];
        if left.is_empty() && right.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        let l_opt = if left.is_empty() {
            None
        } else {
            match left.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        let r_opt = if right.is_empty() {
            None
        } else {
            match right.parse::<u64>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid digit found in string".to_string()),
            }
        };
        Ok((l_opt, r_opt))
    } else {
        if s.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        match s.parse::<u64>() {
            Ok(v) => Ok((Some(v), Some(v))),
            Err(_) => Err("invalid digit found in string".to_string()),
        }
    }
}

fn apply_range(code: &str, range_opt: Option<&String>) -> String {
    if let Some(r) = range_opt {
        if let Ok((start_opt, end_opt)) = parse_range(r) {
            let lines: Vec<&str> = code.lines().collect();
            let total = lines.len() as u64;
            if total == 0 {
                return String::new();
            }
            let start = start_opt.unwrap_or(1);
            let end = end_opt.unwrap_or(total);
            let mut result = Vec::new();
            for (idx, line) in lines.iter().enumerate() {
                let line_num = (idx as u64) + 1;
                if line_num >= start && line_num <= end {
                    result.push(*line);
                }
            }
            return result.join("\n");
        }
    }
    code.to_string()
}

fn generate_png_from_code(code: &str) -> Vec<u8> {
    let lines = code.lines().count().max(1);
    let width: u32 = 800;
    let height: u32 = (100 + lines * 20) as u32;
    let mut raw: Vec<u8> = Vec::with_capacity((width * height * 3 + height) as usize);
    for y in 0..height {
        raw.push(0);
        for x in 0..width {
            let r = ((x as f32 / width as f32 * 100.0) + 107.0) as u8;
            let g = ((y as f32 / height as f32 * 50.0) + 203.0) as u8;
            let b = (165 + (code.len() % 50)) as u8;
            raw.push(r);
            raw.push(g);
            raw.push(b);
        }
    }
    fn adler32(data: &[u8]) -> u32 {
        let mut a: u32 = 1;
        let mut b: u32 = 0;
        for &byte in data {
            a = (a + byte as u32) % 65521;
            b = (b + a) % 65521;
        }
        (b << 16) | a
    }
    let mut zlib_data: Vec<u8> = Vec::new();
    zlib_data.push(0x78);
    zlib_data.push(0x01);
    let mut pos = 0;
    while pos < raw.len() {
        let remaining = raw.len() - pos;
        let chunk_size = std::cmp::min(remaining, 65535);
        let is_final = if pos + chunk_size >= raw.len() { 1 } else { 0 };
        zlib_data.push(is_final as u8);
        let len = chunk_size as u16;
        zlib_data.push((len & 0xFF) as u8);
        zlib_data.push(((len >> 8) & 0xFF) as u8);
        let nlen = !len;
        zlib_data.push((nlen & 0xFF) as u8);
        zlib_data.push(((nlen >> 8) & 0xFF) as u8);
        zlib_data.extend_from_slice(&raw[pos..pos+chunk_size]);
        pos += chunk_size;
    }
    let adler = adler32(&raw);
    zlib_data.push(((adler >> 24) & 0xFF) as u8);
    zlib_data.push(((adler >> 16) & 0xFF) as u8);
    zlib_data.push(((adler >> 8) & 0xFF) as u8);
    zlib_data.push((adler & 0xFF) as u8);
    let mut png: Vec<u8> = Vec::new();
    png.extend_from_slice(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A]);
    let ihdr_data = {
        let mut d = Vec::new();
        d.extend_from_slice(&width.to_be_bytes());
        d.extend_from_slice(&height.to_be_bytes());
        d.push(8);
        d.push(2);
        d.push(0);
        d.push(0);
        d.push(0);
        d
    };
    write_chunk(&mut png, b"IHDR", &ihdr_data);
    write_chunk(&mut png, b"IDAT", &zlib_data);
    write_chunk(&mut png, b"IEND", &[]);
    png
}

fn write_chunk(png: &mut Vec<u8>, typ: &[u8; 4], data: &[u8]) {
    let len = data.len() as u32;
    png.extend_from_slice(&len.to_be_bytes());
    png.extend_from_slice(typ);
    png.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(typ);
    crc_data.extend_from_slice(data);
    let crc = crc32(&crc_data);
    png.extend_from_slice(&crc.to_be_bytes());
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    !crc
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    // Manual help/version to match original exactly and avoid config creation
    if raw_args.iter().any(|a| a == "-h") {
        print!("{}", SHORT_HELP);
        std::process::exit(0);
    }
    if raw_args.iter().any(|a| a == "--help") {
        print!("{}", LONG_HELP);
        std::process::exit(0);
    }
    if raw_args.iter().any(|a| a == "-V" || a == "--version") {
        println!("codesnap-cli 0.13.1");
        std::process::exit(0);
    }

    let mut cmd = Command::new("codesnap")
        .bin_name("codesnap")
        .version("0.13.1")
        .about("CLI tools for generating beautiful code snapshots")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("from-file").short('f').long("from-file").value_name("FROM_FILE").help("Path to the file to snapshot"))
        .arg(Arg::new("from-code").short('c').long("from-code").value_name("Code").num_args(0..=1).default_missing_value("").help("Code snippet for snapshot"))
        .arg(Arg::new("from-image").short('i').long("from-image").value_name("Image").num_args(0..=1).default_missing_value("").help(""))
        .arg(Arg::new("from-clipboard").long("from-clipboard").action(ArgAction::SetTrue).help(""))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").required(true).help("Output path for the snapshot. Available value:\n\n- clipboard: Copy the snapshot to clipboard - file path: Save the snapshot to the file path\n\nCurrently CodeSnap supports SVG format and PNG format If output is directory, CodeSnap will generate a temporary file name to save the snapshot to the directory."))
        .arg(Arg::new("silent").long("silent").action(ArgAction::SetTrue).help(""))
